<script setup>
import {shallowRef,ref,reactive,computed,watch,onBeforeUnmount,nextTick} from 'vue';
import {Button,Field,Cell,CellGroup,Popup,Picker,Checkbox,CheckboxGroup,Switch,Uploader,Pagination,Progress,Collapse,CollapseItem} from 'vant';
import 'vant/es/button/style';import 'vant/es/field/style';import 'vant/es/cell/style';import 'vant/es/cell-group/style';import 'vant/es/popup/style';import 'vant/es/picker/style';import 'vant/es/checkbox/style';import 'vant/es/checkbox-group/style';import 'vant/es/switch/style';import 'vant/es/uploader/style';import 'vant/es/pagination/style';import 'vant/es/progress/style';import 'vant/es/collapse/style';import 'vant/es/collapse-item/style';
import StudentPhotoReview from './StudentPhotoReview.vue';
import StudentPaperAI from './StudentPaperAI.vue';
import StudentFigureEditor from './StudentFigureEditor.vue';
const props=defineProps({controller:{type:Object,required:true}}),m=shallowRef(props.controller.model),a=props.controller.actions,error=ref(''),picker=ref(null),search=ref(''),expanded=ref([]),form=reactive({title:'',examType:'unknown',termName:'',unitIds:[]}),edit=reactive({}),figureQuestion=ref(null),paperSheet=ref();
const unsubscribe=props.controller.subscribe(value=>{m.value=value;});let holdTimer,suppressUntil=0,deletionArmed=true;onBeforeUnmount(()=>{unsubscribe();clearTimeout(holdTimer);});
watch(()=>m.value.paperVersion,()=>{const paper=m.value.paper;if(paper)Object.assign(form,{title:paper.title,...paper.classification,unitIds:[...(paper.classification.unitIds||[])]});},{immediate:true});
watch(()=>m.value.edit,value=>{if(value)Object.assign(edit,value);});
function run(name,...args){try{error.value='';const result=a[name](...args);if(result?.catch)result.catch(e=>{error.value=e.message;});return result;}catch(e){error.value=e.message;}}
function upload(value){const files=(Array.isArray(value)?value:[value]).map(v=>v.file).filter(Boolean);run('addFiles',files);}
const columns=computed(()=>picker.value==='student'?m.value.students.map(s=>({text:s.label,value:s.id})):picker.value==='subject'?[{text:'全部学科',value:''},{text:'数学',value:'math'},{text:'英语',value:'english'},{text:'物理',value:'physics'}]:picker.value==='examType'?Object.entries(m.value.examNames).map(([value,text])=>({text,value})):picker.value==='termName'?[{text:'待核对',value:''},...m.value.terms.map(t=>({text:t,value:t}))]:[{text:'待核对',value:''},...m.value.units.filter(u=>u.subject===m.value.paper?.subject).map(u=>({text:u.termName+' · '+u.title,value:u.id}))]);
function choose({selectedValues}){const key=picker.value,value=selectedValues[0];picker.value=null;if(key==='student')run('selectStudent',value);else if(key==='subject')run('subject',value);else if(key==='editUnit')edit.unitId=value;else{form[key]=value;if(key==='termName'||key==='examType')form.unitIds=[];}}
function hold(job){clearTimeout(holdTimer);holdTimer=setTimeout(()=>{suppressUntil=Date.now()+1200;deletionArmed=false;run('deleteJob',job);},650);}
function release(){clearTimeout(holdTimer);}
function resume(job){if(Date.now()>suppressUntil)run('resume',job.id);}
function changeFormUnits(values){form.unitIds=values;}
function deleteTask(){if(deletionArmed)run('confirmDeleteJob');}
function active(){props.controller.active();return true;}
function back(event){if(!props.controller.actions.canLeave()){event.preventDefault();event.stopPropagation();}}
async function figureChanged(){figureQuestion.value=null;await a.open(m.value.paper.id);}
async function printPaper(){try{error.value='';const questions=m.value.paper.questions;if(questions.some(q=>q.figureError||((q.hasFigureImage||q.hasDrawing||q.figures?.length)&&!q.diagrams?.length)))throw Error('部分题图缺失或未完成，请先核对并补回题图后再打印。');const frame=document.createElement('iframe');frame.title='无答案试卷打印';frame.className='papers-print-frame';document.body.append(frame);const doc=frame.contentDocument;doc.open();doc.write('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>无答案试卷</title><link rel="stylesheet" href="'+new URL('vendor/katex/katex.min.css',location.href).href+'"><style>body{font:16px/1.8 serif;color:#17212b;padding:16px}.paper-question-body{break-inside:avoid;margin:26px 0;min-height:130px}.paper-diagrams svg,.paper-diagrams img{max-width:100%;height:auto}figure{max-width:320px}@page{size:A4;margin:16mm}</style></head><body></body></html>');doc.close();const heading=doc.createElement('h1');heading.textContent=m.value.paper.title;doc.body.append(heading);for(const element of paperSheet.value.querySelectorAll('.paper-question-body'))doc.body.append(element.cloneNode(true));await Promise.all([...doc.querySelectorAll('link')].map(l=>l.sheet?Promise.resolve():new Promise(resolve=>{l.onload=resolve;l.onerror=resolve;})));await doc.fonts.ready;await Promise.all([...doc.images].map(image=>image.decode()));props.controller.active();frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000);}catch(e){error.value=e.message;}}
</script>
<template>
<main class="student-paper-pages" :data-kind="m.kind">
 <Button v-if="!m.wrongOnly" id="question-bank-home" aria-label="返回上一级" icon="arrow-left" @click="back">返回上一级</Button>
 <header v-if="!m.wrongOnly"><div><p>{{m.userLabel}} · {{m.subjectName}}</p><h1>{{m.kind==='papers'?'我的试卷':'拍照题库'}}</h1></div><Button v-if="m.kind==='papers'&&m.view==='list'" type="primary" :disabled="!m.studentId||m.busy" @click="run('newPaper')">拍照试卷</Button></header>
 <p v-if="error" role="alert">{{error}}</p><p role="status" aria-live="polite">{{m.notice}}</p>
 <section v-if="m.userRole!=='Student'" class="student-select"><div v-if="m.userRole==='Admin'" class="actions"><Field v-model="search" label="搜索学生" maxlength="40" :disabled="m.busy" @keydown.enter="run('search',search)"/><Button :disabled="m.busy" @click="run('search',search)">查询</Button></div><Cell title="学生账号" :value="m.students.find(s=>s.id===m.studentId)?.label||'暂无学生'" is-link @click="!m.busy&&(picker='student')"/><div v-if="m.userRole==='Admin'" class="actions"><Button :disabled="m.busy||m.studentPage<=1" @click="run('search',search,m.studentPage-1)">上一页学生</Button><span>第 {{m.studentPage}} 页</span><Button :disabled="m.busy||m.studentPage*m.studentPageSize>=m.studentTotal" @click="run('search',search,m.studentPage+1)">下一页学生</Button></div></section>
 <Cell v-if="m.kind==='papers'&&!m.subjectFixed" title="学科" :value="m.subjectName" is-link @click="(!m.busy||m.running)&&(picker='subject')"/>
 <template v-if="m.studentId">
  <template v-if="m.kind==='papers'&&m.view==='list'"><section v-if="m.jobs.length" class="jobs"><h2>继续整理 / 批改</h2><article v-for="job in m.jobs" :key="job.id" tabindex="0" :aria-label="'待继续任务，按Delete删除'" @keydown.delete.prevent="run('deleteJob',job)" @contextmenu.prevent="run('deleteJob',job)" @pointerdown="hold(job)" @pointerup="release" @pointercancel="release" @pointerleave="release"><strong>{{job.subject==='english'?'英语':job.subject==='physics'?'物理':'数学'}} · {{job.mode==='grade'?'批改':'整理'}}{{job.status==='failed'?'中断':'待继续'}}</strong><p>已规划 {{job.plannedPages}}/{{job.pageCount}} 页 · 已处理 {{job.recognizedQuestions||job.completedQuestions||0}}/{{job.totalQuestions||'?'}} 题</p><p v-if="job.error" role="status">{{job.error}}</p><Button :disabled="m.busy" @click="resume(job)">{{job.status==='failed'?'重试':'继续'}}{{job.mode==='grade'?'批改':'整理'}}</Button><Button :disabled="m.busy" aria-label="删除待整理任务" icon="delete-o" @click="run('deleteJob',job)"/></article></section><CellGroup v-if="m.rows.length"><Cell v-for="paper in m.rows" :key="paper.id" :title="paper.title" clickable @click="run('open',paper.id)"><template #label><span class="paper-card-line">{{paper.questionCount}} 道题 · {{(paper.createdAt||'').slice(0,10)}}{{paper.mode==='paper-draft'?' · 待核对':''}}</span><span class="paper-card-line">{{paper.subject==='english'?'英语':paper.subject==='physics'?'物理':'数学'}} · {{paper.classificationSummary}}</span><span class="paper-card-line">打开试卷 →</span></template></Cell></CellGroup><p v-else>拍下试卷，整理后保存在这里。</p></template>
  <section v-if="m.view==='upload'||m.kind==='bank'&&!m.wrongOnly" class="upload"><Button v-if="m.kind==='papers'" aria-label="返回试卷列表" icon="arrow-left" @click="run('library')">试卷列表</Button><h2>{{m.kind==='papers'?'拍照试卷':'拍照批改'}}</h2><div class="actions"><Uploader :after-read="upload" :preview-image="false" accept="image/jpeg,image/png,image/webp" capture="environment" :disabled="m.busy"><Button :disabled="m.busy">拍照</Button></Uploader><Uploader :after-read="upload" :preview-image="false" accept="image/jpeg,image/png,image/webp" multiple :disabled="m.busy"><Button :disabled="m.busy">相册 / 多页</Button></Uploader><Button type="primary" :disabled="m.busy||!m.photos.length" @click="run('importPhotos')">{{m.kind==='papers'?'整理无答案试卷':'整页逐题批改'}}</Button></div><ol class="photos"><li v-for="(photo,i) in m.photos" :key="photo"><img :src="photo" :alt="'第 '+(i+1)+' 页试卷预览'"><div class="actions"><Button v-if="m.kind==='papers'" :disabled="m.busy" @click="run('rotatePhoto',i)">顺时针旋转第 {{i+1}} 页</Button><Button :disabled="m.busy" :aria-label="'移除第 '+(i+1)+' 页'" icon="cross" @click="run('removePhoto',i)"/></div></li></ol></section>
  <section v-if="m.kind==='bank'" class="bank-questions"><template v-for="q in m.rows" :key="q.id"><article class="bank-question" :aria-label="'第 '+q.number+' 题'"><div :class="['math-prose',{'question-wrong':q.wrong}]"><strong>{{q.number||'?'}}. </strong><span v-html="q.statement"/></div><div class="paper-diagrams"><figure v-for="(diagram,i) in q.diagrams" :key="i"><img v-if="diagram.type==='image'" :src="diagram.src" :alt="'第 '+q.number+' 题插图'"><div v-else v-html="diagram.svg"/></figure></div><div class="actions"><Uploader :after-read="value=>run('answerPhoto',q,(Array.isArray(value)?value:[value]).map(v=>v.file))" :preview-image="false" accept="image/*" capture="environment" :disabled="m.busy"><Button :disabled="m.busy" :aria-label="'第'+q.number+'题拍照答案'">拍照答案</Button></Uploader><Button :aria-expanded="m.reviewQuestion===q.id" :aria-controls="'review-'+q.id" :aria-label="m.reviewQuestion===q.id?'关闭逐题工作台':undefined" :icon="m.reviewQuestion===q.id?'cross':undefined" @click="run('reviewQuestion',q)">{{m.reviewQuestion===q.id?'':'此题批改'}}</Button><Button @click="run('openPaper',q)">查看试卷</Button></div><p v-if="q.format==='legacy'||q.formatError" role="status">题面转换失败：{{q.formatError}} <Button @click="run('retryFormat',q)">重试</Button></p></article><div v-if="m.reviewQuestion===q.id&&m.review" :id="'review-'+q.id"><StudentPhotoReview :controller="m.review"/></div></template><Pagination v-if="m.total>20" :model-value="m.page" :total-items="m.total" :items-per-page="20" @update:model-value="run('page',$event)"/></section>
  <section v-if="m.kind==='papers'&&m.paper&&m.view==='paper'" class="paper-details"><div class="actions"><Button aria-label="返回试卷列表" icon="arrow-left" @click="run('library')">试卷列表</Button><Button @click="run('original',true)">查看原卷</Button><label class="toggle">无答案净卷<Switch :model-value="m.clean" @update:model-value="run('clean',$event)"/></label><label class="toggle">只显示错题（含部分正确）<Switch :model-value="m.onlyWrong" @update:model-value="run('onlyWrong',$event)"/></label><Button @click="printPaper">打印无答案试卷</Button></div>
   <section class="classification"><Field v-model="form.title" label="试卷标题" maxlength="160" :disabled="m.busy"/><Cell title="考试类型" :value="m.examNames[form.examType]" is-link @click="picker='examType'"/><Cell title="册次" :value="form.termName||'待核对'" is-link @click="picker='termName'"/><CheckboxGroup v-if="form.examType==='unit'" :model-value="form.unitIds" @update:model-value="changeFormUnits"><p>对应单元（可多选，同一册次）</p><Checkbox v-for="unit in (m.paper.units||m.units).filter(u=>u.subject===m.paper.subject&&u.termName===form.termName)" :key="unit.id" :name="unit.id">{{unit.title}}</Checkbox><p v-if="!form.termName">请先核对册次。</p></CheckboxGroup><p v-if="m.paper.classification.warnings.length" role="status">{{m.paper.classification.warnings.join('；')}}</p><Collapse v-if="m.paper.classification.evidence" v-model="expanded"><CollapseItem title="识别依据" name="evidence">{{m.paper.classification.evidence}}</CollapseItem></Collapse><p>对照原卷逐题核对题号、公式、选项、题图及单元；核对完成后再保存。</p><Button type="primary" :disabled="m.busy||m.paper.mode==='paper-draft'&&m.paper.questions.some(q=>!q.reviewed)" @click="run('confirm',form)">{{m.paper.mode==='paper-draft'?'核对完成，保存试卷':'保存分类修改'}}</Button></section>
   <h2>{{m.paper.title}}</h2><p v-if="m.paper.warnings?.length" role="status">{{m.paper.warnings.join('；')}}</p><p v-if="m.onlyWrong&&!m.paper.questions.some(q=>q.filterWrong)" role="status">暂无错题或部分正确的题目。</p><div ref="paperSheet"><article v-for="q in m.paper.questions" v-show="!m.onlyWrong||q.filterWrong" :key="q.id" class="paper-question"><div class="paper-question-body"><div :class="['math-prose',{'question-wrong':q.wrong&&!m.clean}]"><strong>{{q.number}}. </strong><span v-html="q.statement"/></div><div class="paper-diagrams"><figure v-for="(diagram,i) in q.diagrams" :key="i"><img v-if="diagram.type==='image'" :src="diagram.src" :alt="'第 '+q.number+' 题插图'"><div v-else v-html="diagram.svg"/></figure></div><p v-if="q.figureError" role="status">题图未完成：{{q.figureError}}，请核对并补回题图后打印。</p></div>
    <Collapse v-if="!m.clean" v-model="expanded"><CollapseItem title="核对 / 修改" :name="'q-'+q.id"><div class="actions"><Button v-if="m.paper.mode==='paper-draft'" :disabled="m.busy||q.reviewed" @click="run('reviewed',q)">{{q.reviewed?'本题已核对':'对照原卷，本题已核对'}}</Button><Button :disabled="m.busy" @click="run('edit',q)">修改题面</Button><Button :disabled="m.busy" @click="run('mark',q)">{{q.wrong?'取消错题标记':'标记为错题'}}</Button><Button :disabled="m.busy" @click="figureQuestion=q">核对 / 补充题图</Button><Button v-if="m.paper.subject==='math'&&(q.figures?.length||q.hasDrawing)&&!q.diagrams.length" :disabled="m.busy" @click="run('draw',q)">补绘题图</Button></div></CollapseItem></Collapse><p v-if="q.uncertain?.length" role="status">{{q.uncertain.join('；')}}</p>
    <StudentPaperAI v-if="!m.clean" :key="q.id+':'+q.revision+':'+m.paperVersion" :api="controller.api" :paper="m.paper" :question="q" :student-id="m.studentId" :active="active"/>
   </article></div>
  </section>
 </template>
 <Popup :show="!!picker" position="bottom" round @update:show="!$event&&(picker=null)"><Picker :columns="columns" @confirm="choose" @cancel="picker=null"><template #cancel><span class="cross" aria-label="关闭">×</span></template></Picker></Popup>
 <Popup :show="m.original" round closeable close-icon="cross" class="original-popup" @update:show="run('original',$event)"><h2>原始试卷</h2><img v-for="page in m.paper?.pages||[]" :key="page.page" :src="page.image" :alt="'第 '+page.page+' 页原卷'"></Popup>
 <Popup :show="!!m.edit" round closeable close-icon="cross" class="form-popup" @update:show="!$event&&run('edit',null)"><h2>核对第 {{edit.number}} 题</h2><Field v-model="edit.number" label="题号" maxlength="40"/><Field v-model="edit.text" type="textarea" rows="10" label="题干与选项" maxlength="6000"/><Cell title="对应单元" :value="m.units.find(u=>u.id===edit.unitId)?.title||'待核对'" is-link @click="picker='editUnit'"/><p>修改题面后旧批改失效，避免将旧错因用于新题。</p><Button type="primary" :disabled="m.busy" @click="run('saveEdit',edit)">保存题面</Button></Popup>
 <Popup :show="!!m.deleteJob" round closeable close-icon="cross" class="form-popup" @update:show="!$event&&run('deleteJob',null)"><h2>删除待整理任务</h2><p>删除这项未完成任务及其照片？已保存的试卷和作答不受影响。删除后无法继续此任务。</p><Button type="danger" :disabled="m.busy" @pointerdown="deletionArmed=true" @keydown="deletionArmed=true" @click="deleteTask">确认删除</Button></Popup>
 <Popup :show="!!m.progress" round closeable close-icon="cross" class="form-popup" @update:show="!$event&&run('stopJob')"><h2>{{m.progress?.mode==='grade'?'正在批改试卷':'正在整理试卷'}}</h2><Progress v-if="Number.isFinite(m.progress?.progressPercent)" :percentage="m.progress.progressPercent"/><p>已规划 {{m.progress?.plannedPages||0}} / {{m.progress?.pageCount||0}} 页 · 已完成 {{m.progress?.completedQuestions||m.progress?.recognizedQuestions||0}} / {{m.progress?.totalQuestions||'?'}} 题</p><p role="status">{{m.progress?.error||m.notice}}</p><Button v-if="m.progress&&!m.running" @click="run('resume',m.progress.id)">重试</Button></Popup>
 <Popup :show="!!figureQuestion" round closeable close-icon="cross" class="form-popup" @update:show="!$event&&(figureQuestion=null)"><StudentFigureEditor v-if="figureQuestion" :key="figureQuestion.id" :api="controller.api" :question="figureQuestion" :student-id="m.studentId" :active="active" :on-changed="figureChanged"/></Popup>
</main>
</template>
<style scoped>
