.student-paper-pages{--van-primary-color:#22634b;--van-button-primary-background:#22634b;--van-button-primary-border-color:#22634b;--van-switch-on-background:#22634b;--van-checkbox-checked-icon-color:#22634b;max-width:1100px;margin:auto;padding:20px clamp(14px,4vw,32px) 60px;color:#24352e;font:16px/1.7 system-ui,-apple-system,"Microsoft YaHei",sans-serif}.student-paper-pages,.student-paper-pages :deep(*){box-sizing:border-box}.student-paper-pages :deep(.van-button){font:inherit;min-height:44px;height:auto;padding:10px 14px;white-space:normal;text-decoration:none}.student-paper-pages header,.actions,.toggle{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.student-paper-pages header{margin:24px 0}.student-paper-pages h1{font-size:32px;margin:0}.student-paper-pages h2{font-size:22px;margin:20px 0 12px}.student-paper-pages p{overflow-wrap:anywhere}.actions{justify-content:flex-start;margin:14px 0}.actions :deep(.van-field){flex:1;min-width:200px}.student-select,.classification,.upload,.jobs article{padding:18px;border:1px solid #dce5dc;border-radius:12px;background:#fff;margin:20px 0}.photos{display:flex;flex-wrap:wrap;gap:20px;padding:0;list-style:none}.photos li{max-width:240px}.photos img,.original-popup img{max-width:100%;height:auto}.bank-question,.paper-question{padding:28px 0;border-bottom:1px solid #dce5dc}.question-wrong{color:#b73838}.paper-diagrams{display:flex;flex-wrap:wrap;gap:18px}.paper-diagrams figure{margin:14px 0;max-width:380px;width:100%}.paper-diagrams :deep(svg),.paper-diagrams img{width:100%;height:auto}.toggle{justify-content:flex-start;gap:10px}.classification :deep(.van-checkbox){margin:12px 0;min-height:44px}.student-paper-pages :deep(.van-popup__close-icon){top:4px;right:4px;min-height:44px;min-width:44px;display:grid;place-items:center}.form-popup,.original-popup{width:min(94vw,760px);max-height:90vh;padding:26px;overflow:auto}.original-popup{width:min(94vw,1000px)}.cross{min-width:44px;min-height:44px;font-size:26px;display:grid;place-items:center}.student-paper-pages :deep(.van-field){padding:14px 10px}.student-paper-pages :deep(.van-cell){min-height:52px}.student-paper-pages :deep(.van-pagination__item){min-height:44px;min-width:44px}.student-paper-pages :deep(.van-uploader__input-wrapper){min-height:44px}.student-paper-pages :deep(.van-cell__title){min-width:0;overflow-wrap:anywhere}.student-paper-pages :deep(.van-cell__value){overflow-wrap:anywhere}.student-paper-pages :deep(.van-popup .van-field){flex-direction:column}.student-paper-pages :deep(.van-popup .van-field__label){width:100%;margin-bottom:8px}.math-prose{overflow-wrap:anywhere}.student-paper-pages :deep(.katex-display){overflow:auto}.student-paper-pages a:focus-visible{outline:3px solid #22634b;outline-offset:3px}@media(max-width:500px){.student-paper-pages header{align-items:start}.photos li{max-width:100%}.student-select,.classification,.upload,.jobs article{padding:14px}.student-paper-pages :deep(.van-cell){padding:14px 10px}}
</style>

<style scoped>
.paper-card-line{display:block;margin-top:12px;font-size:14px;line-height:1.65;color:#25332c}.student-paper-pages :deep(.van-cell-group .van-cell__label){margin-top:0}.paper-question>.van-collapse :deep(.van-cell){min-height:0}.paper-question>.van-collapse :deep(.van-collapse-item__wrapper){border:0}.paper-question>.van-collapse :deep(.van-hairline--top-bottom:after){display:none}
</style>

<style scoped>
/* visual-restore-legacy */
